#!/usr/bin/env python3
"""Write docs/reference/parameters.md from nextflow_schema.json.

Run from anywhere after changing the schema:
    python3 docs/_scripts/schema_to_md.py

Adapted from nf-cellbender's docs/_scripts/schema_to_md.py.
"""
import json
import pathlib

ROOT = pathlib.Path(__file__).resolve().parents[2]
SCHEMA = ROOT / "nextflow_schema.json"
OUT = ROOT / "docs" / "reference" / "parameters.md"

FRONT_MATTER = """---
title: Parameters
parent: Reference
nav_order: 1
---

<!-- Generated by docs/_scripts/schema_to_md.py from nextflow_schema.json. Do not edit by hand: change the schema and rerun the script. -->

# Parameters
{: .no_toc }

Every parameter the pipeline accepts, grouped as in `--help`. They are checked against
[`nextflow_schema.json`](https://github.com/cellgeni/nf-reprocessing-public-10x/blob/main/nextflow_schema.json)
before anything is fetched: a wrong type (`--starsolo ture`), an unknown species or a missing
`--datasets` stops the run at once. `nextflow run main.nf --help` prints the same list.

1. TOC
{:toc}
"""

# Rules main.nf enforces itself, after the schema: they span parameters and profiles, which
# the schema cannot see. Keep in step with the checks after validateParameters() in main.nf.
MAIN_NF_RULES = [
    "`--no_infer_specie` needs `--default_specie`.",
    "A container engine is required: run with `-profile sanger`, `singularity` or `docker`.",
    "`--wl_basedir` is required unless `--metaonly` is set.",
    "`--starsolo` needs `--star_human_reference` or `--star_mouse_reference`, and `--cellranger` "
    "needs `--cr_human_reference` or `--cr_mouse_reference`. With only one of the two, the other "
    "species' samples are not aligned, and a warning says so.",
]


def cell(text):
    """Make text safe for a Markdown table cell."""
    return str(text).replace("|", "\\|").replace("\n", " ").strip()


def type_of(spec):
    kinds = spec.get("type", "")
    kinds = " or ".join(kinds) if isinstance(kinds, list) else kinds
    if spec.get("format") in ("file-path", "directory-path"):
        kinds += f" ({spec['format'].replace('-path', '')})"
    return kinds


def default_of(spec):
    if "default" not in spec:
        return "–"
    value = spec["default"]
    if isinstance(value, bool):
        value = str(value).lower()
    return f"`{value}`"


def details_of(spec):
    parts = [spec.get("description", "")]
    if "enum" in spec:
        values = []
        for v in spec["enum"]:
            if str(v) not in values:
                values.append(str(v))
        parts.append("Allowed: " + ", ".join(f"`{v}`" for v in values) + ".")
    if "minimum" in spec or "maximum" in spec or "exclusiveMinimum" in spec:
        bounds = []
        if "minimum" in spec:
            bounds.append(f"≥ {spec['minimum']}")
        if "exclusiveMinimum" in spec:
            bounds.append(f"> {spec['exclusiveMinimum']}")
        if "maximum" in spec:
            bounds.append(f"≤ {spec['maximum']}")
        parts.append("Range: " + ", ".join(bounds) + ".")
    if spec.get("help_text"):
        parts.append(spec["help_text"])
    return cell(" ".join(p for p in parts if p))


def rules_of(schema):
    """Cross-parameter rules: the errorMessages of the root allOf conditionals."""
    rules = []
    for entry in schema.get("allOf", []):
        if "if" not in entry:
            continue
        then = entry.get("then", {})
        if then.get("errorMessage"):
            rules.append(then["errorMessage"])
        for spec in then.get("properties", {}).values():
            if spec.get("errorMessage"):
                rules.append(spec["errorMessage"])
    return rules


def main():
    schema = json.loads(SCHEMA.read_text())
    lines = [FRONT_MATTER]
    hidden = []
    for group in schema["$defs"].values():
        required = set(group.get("required", []))
        rows = []
        for name, spec in group["properties"].items():
            row = f"| `--{name}`{' (required)' if name in required else ''} | {type_of(spec)} | {default_of(spec)} | {details_of(spec)} |"
            (hidden if spec.get("hidden") else rows).append(row)
        if not rows:
            continue
        lines.append(f"## {group['title']}\n")
        if group.get("description"):
            lines.append(group["description"] + "\n")
        lines.append("| Parameter | Type | Default | Description |\n|---|---|---|---|")
        lines.extend(rows)
        lines.append("")

    lines.append("## Rules across parameters\n")
    lines.append("Combinations that stop the run at launch:\n")
    lines.extend(f"- {rule}" for rule in rules_of(schema) + MAIN_NF_RULES)
    lines.append("")

    if hidden:
        lines.append("## Hidden parameters\n")
        lines.append("Not shown by `--help`; `--help --showHidden` lists them.\n")
        lines.append("| Parameter | Type | Default | Description |\n|---|---|---|---|")
        lines.extend(hidden)
        lines.append("")

    OUT.parent.mkdir(parents=True, exist_ok=True)
    OUT.write_text("\n".join(lines))
    print(f"wrote {OUT.relative_to(ROOT)}")


if __name__ == "__main__":
    main()
